-- Run after the additive migration inside a transaction; always roll back fixtures.
-- Uses existing identity IDs only. Does not modify users, send invitations or invoke a model.
create temp table test_results(name text primary key);
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERTION_FAILED: %',label; end if; insert into test_results values(label); end $$;
create function pg_temp.expect_error(command text,expected text,label text) returns void language plpgsql as $$
declare observed text;
begin begin execute command; exception when others then observed:=sqlerrm; end;
if observed is null or position(expected in observed)=0 then raise exception 'ASSERTION_FAILED: % (observed %)',label,observed; end if;
insert into test_results values(label);
end $$;
grant select,insert on test_results to authenticated,anon;
select set_config('test.owner',(select id::text from auth.users order by id limit 1),true);
select set_config('test.editor',(select id::text from auth.users order by id offset 1 limit 1),true);
select set_config('test.viewer',(select id::text from auth.users order by id offset 2 limit 1),true);
select pg_temp.assert_true(current_setting('test.viewer')<>'','three existing test identities');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.owner'),'email','owner@example.invalid','role','authenticated')::text,true);
set local role authenticated;
select set_config('test.workspace',(public.team_action('create',null,'{"name":"Transactional security test"}')->>'workspace_id'),true);
select pg_temp.assert_true((select count(*)=1 from team_workspaces),'owner sees workspace');
select pg_temp.expect_error(format('insert into team_members values(%L,%L,''admin'',now())',current_setting('test.workspace'),current_setting('test.viewer')),'permission denied','direct membership writes denied');
select pg_temp.expect_error(format('select team_action(''remove_member'',%L,%L)',current_setting('test.workspace'),jsonb_build_object('user_id',current_setting('test.owner'))::text),'OWNER_PROTECTED','owner cannot be removed');
select set_config('test.token',(public.team_action('invite',current_setting('test.workspace')::uuid,'{"email":"editor@example.invalid","role":"editor"}')->>'token'),true);
select pg_temp.assert_true(length(current_setting('test.token'))=64,'invite token has 256 bits');
select pg_temp.assert_true(not exists(select 1 from team_invites where token_hash=current_setting('test.token')),'only token hash stored');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.viewer'),'email','wrong@example.invalid','role','authenticated')::text,true);
select pg_temp.assert_true((select count(*)=0 from team_workspaces),'outsider cannot read another workspace');
select pg_temp.expect_error(format('select team_action(''accept'',null,%L)',jsonb_build_object('token',current_setting('test.token'))::text),'INVALID_INVITE','wrong email cannot accept');
select pg_temp.expect_error(format('select team_action(''invite'',%L,''{}'')',current_setting('test.workspace')),'NOT_A_MEMBER','outsider cannot mutate tenant');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.editor'),'email','editor@example.invalid','role','authenticated')::text,true);
select public.team_action('accept',null,jsonb_build_object('token',current_setting('test.token')));
select pg_temp.assert_true(public.team_role(current_setting('test.workspace')::uuid)='editor','matching email joins with invited role');
select pg_temp.expect_error(format('select team_action(''accept'',null,%L)',jsonb_build_object('token',current_setting('test.token'))::text),'INVALID_INVITE','invite is single-use');
select pg_temp.expect_error(format('select team_action(''invite'',%L,''{"email":"x@example.invalid","role":"admin"}'')',current_setting('test.workspace')),'ADMIN_REQUIRED','editor cannot invite administrators');
select set_config('test.skill',(public.team_action('submit_skill',current_setting('test.workspace')::uuid,'{"slug":"test-skill","version":"0.1.0","name":"Test skill","files":{"SKILL.md":"Test body"}}')->>'id'),true);
select pg_temp.assert_true((select count(*)=1 from team_skill_versions),'editor can submit a private version');
select pg_temp.expect_error(format('select team_action(''submit_skill'',%L,''{"slug":"bad-skill","version":"0.1.0","name":"Bad skill","files":{"SKILL.md":"Test","../escape":"bad"}}'')',current_setting('test.workspace')),'INVALID_FILES','RPC rejects traversal paths');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.owner'),'email','owner@example.invalid','role','authenticated')::text,true);
select public.team_action('set_role',current_setting('test.workspace')::uuid,jsonb_build_object('user_id',current_setting('test.editor'),'role','admin'));
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.editor'),'email','editor@example.invalid','role','authenticated')::text,true);
select pg_temp.expect_error(format('select team_action(''review_skill'',%L,%L)',current_setting('test.workspace'),jsonb_build_object('id',current_setting('test.skill'),'status','approved')::text),'INDEPENDENT_REVIEW_REQUIRED','creator cannot approve their own version');
reset role;
insert into team_members(workspace_id,user_id,role) values(current_setting('test.workspace')::uuid,current_setting('test.viewer')::uuid,'viewer');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.viewer'),'email','viewer@example.invalid','role','authenticated')::text,true);
select pg_temp.assert_true((select count(*)=0 from team_skill_versions),'viewer cannot read pending private skill');
select pg_temp.assert_true((select count(*)=0 from team_invites),'viewer cannot read invite hashes');
select pg_temp.assert_true((select count(*)=0 from team_audit_events),'viewer cannot read audit events');
select pg_temp.expect_error(format('select team_action(''submit_skill'',%L,''{}'')',current_setting('test.workspace')),'EDITOR_REQUIRED','viewer cannot submit');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.owner'),'email','owner@example.invalid','role','authenticated')::text,true);
select public.team_action('review_skill',current_setting('test.workspace')::uuid,jsonb_build_object('id',current_setting('test.skill'),'status','approved'));
select pg_temp.assert_true(not exists(select 1 from team_audit_events where detail ?| array['email','token','files']),'audit excludes files tokens and email');
select set_config('test.expired',(public.team_action('invite',current_setting('test.workspace')::uuid,'{"email":"viewer@example.invalid","role":"admin"}')->>'token'),true);
reset role;
update team_invites set expires_at=now()-interval '1 minute' where token_hash=encode(extensions.digest(current_setting('test.expired'),'sha256'),'hex');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.viewer'),'email','viewer@example.invalid','role','authenticated')::text,true);
select pg_temp.expect_error(format('select team_action(''accept'',null,%L)',jsonb_build_object('token',current_setting('test.expired'))::text),'INVALID_INVITE','expired invitation denied');
select pg_temp.assert_true((select count(*)=1 from team_skill_versions),'viewer can read independently approved private version');
select pg_temp.expect_error(format('update team_skill_versions set files=''{}'' where id=%L',current_setting('test.skill')),'permission denied','private approved content immutable');
select pg_temp.expect_error(format('select team_action(''pin_package'',%L,''{"slug":"absent","version":"0.0.0"}'')',current_setting('test.workspace')),'ADMIN_REQUIRED','viewer cannot pin public packages');
select set_config('request.jwt.claims','{}',true);
select pg_temp.expect_error('select team_action(''create'',null,''{"name":"Unauthorized"}'')','AUTH_REQUIRED','missing identity denied');
reset role;
select pg_temp.assert_true(not has_table_privilege('authenticated','package_artifacts','UPDATE'),'archive updates unavailable to authenticated');
select pg_temp.assert_true(not has_table_privilege('anon','team_workspaces','SELECT'),'anonymous workspace access unavailable');
select pg_temp.assert_true(not has_function_privilege('anon','public.team_action(text,uuid,jsonb)','EXECUTE'),'anonymous mutation RPC unavailable');

select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.owner'),'email','owner@example.invalid','role','authenticated')::text,true);
set local role authenticated;
select set_config('test.rejoin',(public.team_action('invite',current_setting('test.workspace')::uuid,'{"email":"viewer@example.invalid","role":"admin"}')->>'token'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.viewer'),'email','viewer@example.invalid','role','authenticated')::text,true);
select public.team_action('accept',null,jsonb_build_object('token',current_setting('test.rejoin')));
select pg_temp.assert_true(public.team_role(current_setting('test.workspace')::uuid)='viewer','accepting another invite cannot promote existing member');
reset role;
select set_config('test.public_package',(select p.id::text from packages p join package_versions v on v.package_id=p.id and v.version=p.latest_version left join package_artifacts a on a.version_id=v.id where p.is_published and p.review_status='approved' and p.price_credits=0 and a.version_id is null order by p.slug limit 1),true);
select set_config('test.public_version',(select v.id::text from package_versions v join packages p on p.id=v.package_id where p.id=current_setting('test.public_package')::uuid and v.version=p.latest_version limit 1),true);
select set_config('test.old_version',(gen_random_uuid()::text),true);
insert into package_versions(id,package_id,version,system_prompt) values(current_setting('test.old_version')::uuid,current_setting('test.public_package')::uuid,'0.0.0-security-fixture','Unreviewed transactional fixture');
insert into package_artifacts(version_id,package_id,files,sha256) values(current_setting('test.public_version')::uuid,current_setting('test.public_package')::uuid,'{"source.md":"Current approved version fixture"}',repeat('a',64));
insert into package_artifacts(version_id,package_id,files,sha256) values(current_setting('test.old_version')::uuid,current_setting('test.public_package')::uuid,'{"source.md":"Unreviewed old version fixture"}',repeat('b',64));
select pg_temp.expect_error(format('insert into package_artifacts(version_id,package_id,files,sha256) values(%L,%L,''{}'',%L)',current_setting('test.public_version'),(select id from packages where id<>current_setting('test.public_package')::uuid limit 1),repeat('c',64)),'VERSION_MISMATCH','archive cannot reference another package version');
select pg_temp.expect_error(format('update public.packages set latest_version=''0.0.0-security-fixture'' where id=%L',current_setting('test.public_package')),'current version has no adversarial run','published version cannot switch to unevaluated source');
select set_config('request.jwt.claims','{}',true);
set local role anon;
select pg_temp.assert_true((select count(*)=0 from package_artifacts where version_id=current_setting('test.public_version')::uuid),'anonymous direct archive read denied; distribution uses gated public API');
select pg_temp.assert_true((select count(*)=0 from package_artifacts where version_id=current_setting('test.old_version')::uuid),'anonymous reader cannot see unreviewed version archive');
select pg_temp.assert_true((select count(*)=0 from skill_compatibility),'anonymous direct compatibility reads denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.owner'),'email','owner@example.invalid','role','authenticated')::text,true);
set local role authenticated;
select public.team_action('pin_package',current_setting('test.workspace')::uuid,(select jsonb_build_object('slug',slug,'version',latest_version) from packages where id=current_setting('test.public_package')::uuid));
select pg_temp.assert_true((select version_id=current_setting('test.public_version')::uuid from team_library where workspace_id=current_setting('test.workspace')::uuid),'pin locks exact approved version');
select pg_temp.expect_error(format('select team_action(''pin_package'',%L,%L)',current_setting('test.workspace'),(select jsonb_build_object('slug',slug,'version','0.0.0-security-fixture')::text from packages where id=current_setting('test.public_package')::uuid)),'APPROVED_VERSION_REQUIRED','unreviewed version cannot be pinned');
reset role;

select count(*) as passed, jsonb_agg(name order by name) as assertions from test_results;
